<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) by Piet Mondrian</title>
<meta name="description" content="Piet Mondrian's 1930 De Stijl painting Composition with Red, Blue and Yellow: the painter, the year, the movement and why it matters.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
  :root {
    --red: #d7231d; --blue: #1b3fa0; --yellow: #f6d10a;
    --black: #0d0d0d; --white: #f7f5ef; --grey: #c9c6bd;
    --line: 14px;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html { scroll-behavior: smooth; }
  body {
    font-family: "Archivo", Helvetica, Arial, sans-serif;
    background: var(--white); color: var(--black);
    line-height: 1.5; -webkit-font-smoothing: antialiased;
  }
  a { color: inherit; }
  a:focus-visible { outline: 4px solid var(--blue); outline-offset: 3px; }
  .visually-hidden { position: absolute; left: -9999px; }

  /* Every section is a Mondrian grid: cells divided by thick black lines */
  .mondrian { display: grid; gap: var(--line); background: var(--black); border: var(--line) solid var(--black); border-bottom: 0; }
  .cell { background: var(--white); }
  .cell.red { background: var(--red); color: var(--white); }
  .cell.blue { background: var(--blue); color: var(--white); }
  .cell.yellow { background: var(--yellow); }
  .cell.grey { background: var(--grey); }

  /* Hero follows the picture: large red top right, small blue bottom left, small yellow bottom right */
  .hero {
    min-height: 100vh;
    grid-template-columns: 1fr 2.4fr;
    grid-template-rows: 1fr 2.4fr 1fr;
  }
  .hero .title { grid-column: 1; grid-row: 1 / 3; padding: clamp(1.5rem, 4vw, 3.5rem); display: flex; flex-direction: column; justify-content: flex-end; }
  .hero .red   { grid-column: 2; grid-row: 1 / 3; display: flex; align-items: flex-end; justify-content: flex-end; padding: clamp(1.5rem, 4vw, 3.5rem); }
  .hero .blue  { grid-column: 1; grid-row: 3; display: flex; align-items: center; padding: 1.5rem; }
  .hero .bottom-right { grid-column: 2; grid-row: 3; display: grid; grid-template-columns: 3fr 1fr; gap: var(--line); background: var(--black); }
  .hero .bottom-right .cell { padding: 1.5rem; display: flex; align-items: center; }

  .eyebrow { font-size: 0.8rem; letter-spacing: 0.18em; text-transform: uppercase; font-weight: 700; margin-bottom: 1rem; }
  h1 { font-weight: 900; font-size: clamp(2.2rem, 5.5vw, 5.2rem); line-height: 0.95; letter-spacing: -0.02em; text-wrap: balance; }
  .hero .red .year { font-weight: 900; font-size: clamp(5rem, 16vw, 15rem); line-height: 0.85; letter-spacing: -0.04em; }
  .hero .blue p, .hero .bottom-right p { font-weight: 700; font-size: clamp(1rem, 1.6vw, 1.3rem); }
  .hero .bottom-right .white a { font-weight: 700; text-decoration: none; border-bottom: 4px solid var(--black); }

  /* Facts */
  .facts { grid-template-columns: repeat(12, 1fr); }
  .facts .cell { padding: clamp(1.5rem, 3vw, 3rem); }
  .facts .facts-label { font-size: 0.8rem; letter-spacing: 0.18em; text-transform: uppercase; font-weight: 700; opacity: 0.8; margin-bottom: 0.5rem; }
  .facts .facts-value { font-weight: 900; font-size: clamp(1.4rem, 2.6vw, 2.4rem); line-height: 1.1; letter-spacing: -0.01em; }
  .facts .facts-value small { display: block; font-weight: 500; font-size: 1rem; letter-spacing: 0; margin-top: 0.5rem; opacity: 0.9; }
  .f-painter { grid-column: span 5; }
  .f-year { grid-column: span 3; }
  .f-medium { grid-column: span 4; }
  .f-movement { grid-column: span 8; }
  .f-collection { grid-column: span 4; }

  /* Rules */
